634		s.mu.RLock()
635		defer s.mu.RUnlock()
636		state, ok := s.devices[id]
637		if !ok {
638			return Rule{}, ErrDeviceNotFound
639		}
640		rs, ok := state.rules[ruleID]
641		if !ok {
642			return Rule{}, ErrRuleNotFound
643		}
644		return cloneRule(rs.rule), nil
645	}
